package com.thievingstalls;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ThievingStallsPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ThievingStallsPlugin.class);
		RuneLite.main(args);
	}
}

package com.thievingstalls;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class RatesTest
{
	@Test
	public void testNotEnoughData()
	{
		assertEquals(-1, Rates.perHour(100, 1, 0, 0));
		assertEquals(-1, Rates.perHour(100, 2, 5000, 5000));
	}

	@Test
	public void testPerHour()
	{
		// 3 steals, one every 3s: 2 intervals over 6s -> 1200 steals/hr
		assertEquals(1200, Rates.perHour(3, 3, 0, 6000));
		// 300gp over 3 steals is 100gp/steal -> 120k gp/hr
		assertEquals(120_000, Rates.perHour(300, 3, 0, 6000));
	}

	@Test
	public void testTimeToLevel()
	{
		assertEquals(-1, Rates.millisToGain(1000, -1));
		// 30k xp at 60k xp/hr is 30 minutes
		assertEquals(1_800_000, Rates.millisToGain(30_000, 60_000));
		assertEquals("00:30", Rates.formatHoursMinutes(1_800_000));
		assertEquals("01:01", Rates.formatHoursMinutes(3_600_001));
		assertEquals("125:00", Rates.formatHoursMinutes(125 * 3_600_000L));
	}
}

package com.thievingstalls;

import static org.junit.Assert.assertEquals;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

public class StallRecordTest
{
	@Test
	public void testSlugify()
	{
		assertEquals("bakers-stall", StallRecord.slugify("Baker's stall"));
		assertEquals("cannonball-stall", StallRecord.slugify("Cannonball stall"));
		assertEquals("fruit-stall", StallRecord.slugify("Fruit Stall"));
		assertEquals("unknown-stall", StallRecord.slugify(""));
		assertEquals("unknown-stall", StallRecord.slugify(null));
	}

	@Test
	public void testAddSteal()
	{
		StallRecord record = new StallRecord("Baker's stall");
		record.addSteal(Collections.singletonList(new LootItem(1891, "Cake", 1, 30)), 16, 1000);
		record.addSteal(Arrays.asList(new LootItem(1891, "Cake", 1, 30), new LootItem(2309, "Bread", 1, 7)), 16, 2000);

		assertEquals(2, record.getSteals());
		assertEquals(1000, record.getFirstSteal());
		assertEquals(2000, record.getLastSteal());
		assertEquals(32, record.getXp());
		assertEquals(2, record.getItems().size());
		assertEquals(2, record.getItems().get(0).getQuantity());
		assertEquals(1, record.getItems().get(1).getQuantity());
	}

	@Test
	public void testMerge()
	{
		StallRecord saved = new StallRecord("Silk stall");
		saved.addSteal(Collections.singletonList(new LootItem(950, "Silk", 1, 30)), 24, 5000);

		StallRecord unsaved = new StallRecord("Silk stall");
		unsaved.addSteal(Collections.singletonList(new LootItem(950, "Silk", 1, 30)), 24, 9000);

		saved.merge(unsaved);
		assertEquals(2, saved.getSteals());
		assertEquals(5000, saved.getFirstSteal());
		assertEquals(9000, saved.getLastSteal());
		assertEquals(48, saved.getXp());
		assertEquals(2, saved.getItems().get(0).getQuantity());
	}

	@Test
	public void testCopyIsDeep()
	{
		StallRecord record = new StallRecord("Silk stall");
		record.addSteal(Collections.singletonList(new LootItem(950, "Silk", 1, 30)), 24, 5000);

		StallRecord copy = record.copy();
		copy.getItems().get(0).setQuantity(100);
		assertEquals(1, record.getItems().get(0).getQuantity());
	}
}

