package com.thievingstalls;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Aggregated loot for a single stall type. This is the shape of each stall's json file.
 */
@Data
@NoArgsConstructor
public class StallRecord
{
	static final int CURRENT_VERSION = 1;

	private int version = CURRENT_VERSION;
	private String stall;
	private long steals;
	/**
	 * Thieving xp gained from this stall
	 */
	private long xp;
	/**
	 * Epoch millis of the first and most recent successful steal
	 */
	private long firstSteal;
	private long lastSteal;
	private List<LootItem> items = new ArrayList<>();

	StallRecord(String stall)
	{
		this.stall = stall;
	}

	public String getSlug()
	{
		return slugify(stall);
	}

	void addSteal(List<LootItem> loot, long xp, long time)
	{
		this.xp += xp;
		if (steals == 0 || firstSteal == 0)
		{
			firstSteal = time;
		}
		lastSteal = Math.max(lastSteal, time);
		steals++;
		addItems(loot);
	}

	/**
	 * Merge another record of the same stall into this one
	 */
	void merge(StallRecord other)
	{
		steals += other.steals;
		xp += other.xp;
		if (other.firstSteal != 0 && (firstSteal == 0 || other.firstSteal < firstSteal))
		{
			firstSteal = other.firstSteal;
		}
		lastSteal = Math.max(lastSteal, other.lastSteal);
		addItems(other.items);
	}

	private void addItems(List<LootItem> loot)
	{
		for (LootItem add : loot)
		{
			LootItem existing = null;
			for (LootItem item : items)
			{
				if (item.getId() == add.getId())
				{
					existing = item;
					break;
				}
			}

			if (existing == null)
			{
				items.add(add.copy());
			}
			else
			{
				existing.setQuantity(existing.getQuantity() + add.getQuantity());
			}
		}
	}

	StallRecord copy()
	{
		StallRecord copy = new StallRecord(stall);
		copy.version = version;
		copy.steals = steals;
		copy.xp = xp;
		copy.firstSteal = firstSteal;
		copy.lastSteal = lastSteal;
		for (LootItem item : items)
		{
			copy.items.add(item.copy());
		}
		return copy;
	}

	/**
	 * Converts a stall name into a file-safe name, e.g. "Baker's stall" -> "bakers-stall"
	 */
	static String slugify(String name)
	{
		String slug = name == null ? "" : name.toLowerCase(Locale.ROOT)
			.replace("'", "")
			.replaceAll("[^a-z0-9]+", "-")
			.replaceAll("^-+|-+$", "");
		return slug.isEmpty() ? "unknown-stall" : slug;
	}
}

package com.thievingstalls;

public final class Rates
{
	private static final long HOUR_MILLIS = 3_600_000L;

	private Rates()
	{
	}

	/**
	 * Hourly rate of {@code total}, measured between the first and last steal so it doesn't decay while idle.
	 * The first steal starts the clock, so only the {@code steals - 1} steals after it count towards the rate.
	 *
	 * @param total the amount gained over all steals, e.g. loot value, or the number of steals itself
	 * @param steals number of steals
	 * @param firstSteal epoch millis of the first steal
	 * @param lastSteal epoch millis of the last steal
	 * @return the hourly rate, or -1 if there isn't enough data yet
	 */
	public static long perHour(long total, long steals, long firstSteal, long lastSteal)
	{
		long elapsed = lastSteal - firstSteal;
		if (steals < 2 || elapsed <= 0)
		{
			return -1;
		}
		return (long) ((double) total / steals * (steals - 1) * HOUR_MILLIS / elapsed);
	}

	/**
	 * @return millis needed to gain {@code remaining} at {@code perHour}, or -1 if the rate is unknown
	 */
	public static long millisToGain(long remaining, long perHour)
	{
		if (perHour <= 0)
		{
			return -1;
		}
		return (long) Math.ceil((double) Math.max(remaining, 0) * HOUR_MILLIS / perHour);
	}

	/**
	 * Formats a duration as HH:MM, rounding up to the next minute
	 */
	public static String formatHoursMinutes(long millis)
	{
		long minutes = (millis + 59_999) / 60_000;
		return String.format("%02d:%02d", minutes / 60, minutes % 60);
	}
}

package com.thievingstalls;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.QuantityFormatter;

class ThievingStallsOverlay extends OverlayPanel
{
	private final ThievingStallsPlugin plugin;
	private final ThievingStallsConfig config;

	@Inject
	ThievingStallsOverlay(ThievingStallsPlugin plugin, ThievingStallsConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		StallRecord record = plugin.getOverlayRecord();
		if (!config.showOverlay() || record == null)
		{
			return null;
		}

		long now = System.currentTimeMillis();
		if (now - record.getLastSteal() > config.overlayTimeout() * 60_000L)
		{
			return null;
		}

		long value = plugin.getOverlaySessionValue();
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(record.getStall())
			.build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Steals:")
			.right(QuantityFormatter.formatNumber(record.getSteals()))
			.build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Loot value:")
			.right(QuantityFormatter.quantityToStackSize(value) + " gp")
			.build());

		long stealsPerHour = Rates.perHour(record.getSteals(), record.getSteals(), record.getFirstSteal(), record.getLastSteal());
		long gpPerHour = Rates.perHour(value, record.getSteals(), record.getFirstSteal(), record.getLastSteal());
		if (stealsPerHour != -1)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Steals/hr:")
				.right(QuantityFormatter.formatNumber(stealsPerHour))
				.build());
			panelComponent.getChildren().add(LineComponent.builder()
				.left("GP/hr:")
				.right(QuantityFormatter.quantityToStackSize(gpPerHour))
				.build());
			panelComponent.getChildren().add(LineComponent.builder()
				.left("XP/hr:")
				.right(QuantityFormatter.formatNumber(
					Rates.perHour(record.getXp(), record.getSteals(), record.getFirstSteal(), record.getLastSteal())))
				.build());
		}

		return super.render(graphics);
	}
}

package com.thievingstalls;

import com.google.common.collect.HashMultiset;
import com.google.common.collect.Multiset;
import com.google.common.collect.Multisets;
import com.google.inject.Provides;
import com.thievingstalls.ui.ThievingStallsPanel;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Thieving Stalls Loot Tracker",
	description = "Tracks loot stolen from thieving stalls, grouped by stall",
	tags = {"thieving", "stall", "loot", "tracker", "steal"},
	internalName = "thieving-stalls-loot-tracker"
)
public class ThievingStallsPlugin extends Plugin
{
	private static final Pattern STEAL_MESSAGE = Pattern.compile("^You steal .*", Pattern.CASE_INSENSITIVE);
	/**
	 * How many ticks after a steal message we wait for the matching inventory update
	 */
	private static final int LOOT_WAIT_TICKS = 2;
	/**
	 * How many ticks apart a steal and its xp drop may arrive
	 */
	private static final int XP_WAIT_TICKS = 1;
	private static final String UNKNOWN_STALL = "Unknown stall";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ThievingStallsConfig config;

	@Inject
	private ItemManager itemManager;

	@Inject
	private SkillIconManager skillIconManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ThievingStallsOverlay overlay;

	@Inject
	private LootStore store;

	private ThievingStallsPanel panel;
	private NavigationButton navButton;

	/**
	 * The stall most recently clicked with "Steal-from"
	 */
	private String targetStall;
	private Multiset<Integer> lastInventory;
	/**
	 * Tick a steal message was seen whose loot hasn't arrived yet, or -1
	 */
	private int pendingStealTick = -1;
	/**
	 * Inventory additions that arrived before the steal message in the same tick
	 */
	private Multiset<Integer> unclaimedAdditions;
	private int unclaimedAdditionsTick = -1;
	/**
	 * Stall shown on the overlay, the one most recently stolen from
	 */
	private String overlayStall;

	private int lastThievingXp = -1;
	/**
	 * Thieving xp gained before its steal was recorded, and the tick it was gained on or -1
	 */
	private long pendingXp;
	private int pendingXpTick = -1;
	/**
	 * The most recently recorded steal, so xp arriving after it can be credited to its stall
	 */
	private String lastStealStall;
	private int lastStealTick = -1;
	private boolean lastStealHasXp;

	/**
	 * Stall and session record the overlay displays. Written on the client thread, read on the render thread.
	 */
	@Getter
	private volatile StallRecord overlayRecord;
	@Getter
	private volatile long overlaySessionValue;

	@Override
	protected void startUp() throws Exception
	{
		panel = injector.getInstance(ThievingStallsPanel.class);
		store.setChangeListener(this::onStoreChanged);
		store.start(this::getPluginDirectory);

		BufferedImage icon = skillIconManager.getSkillImage(Skill.THIEVING, true);
		navButton = NavigationButton.builder()
			.tooltip("Thieving Stalls")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(overlay);

		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				store.setAccount(client.getAccountHash());
				lastInventory = snapshotInventory(client.getItemContainer(InventoryID.INV));
				lastThievingXp = client.getSkillExperience(Skill.THIEVING);
			}
			refresh();
		});
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		clientToolbar.removeNavigation(navButton);
		store.setChangeListener(null);
		store.shutDown();

		navButton = null;
		panel = null;
		targetStall = null;
		lastInventory = null;
		pendingStealTick = -1;
		unclaimedAdditions = null;
		unclaimedAdditionsTick = -1;
		overlayStall = null;
		lastThievingXp = -1;
		pendingXp = 0;
		pendingXpTick = -1;
		lastStealStall = null;
		lastStealTick = -1;
		lastStealHasXp = false;
		overlayRecord = null;
		overlaySessionValue = 0;
	}

	@Provides
	ThievingStallsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ThievingStallsConfig.class);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			store.setAccount(client.getAccountHash());
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			// Inventory and stats are re-sent on login, don't treat that as loot or xp
			lastInventory = null;
			pendingStealTick = -1;
			unclaimedAdditions = null;
			lastThievingXp = -1;
			pendingXpTick = -1;
			lastStealStall = null;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ThievingStallsConfig.GROUP.equals(event.getGroup()) && "priceType".equals(event.getKey()))
		{
			clientThread.invokeLater(this::refresh);
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (isGameObjectOption(event.getMenuAction())
			&& event.getMenuOption() != null
			&& event.getMenuOption().startsWith("Steal"))
		{
			targetStall = Text.removeTags(event.getMenuTarget()).trim();
			log.debug("Targeting stall {}", targetStall);
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());
		if (!STEAL_MESSAGE.matcher(message).matches())
		{
			return;
		}

		int tick = client.getTickCount();
		if (unclaimedAdditions != null && unclaimedAdditionsTick == tick)
		{
			// Inventory updated before the message this tick
			recordSteal(unclaimedAdditions);
			unclaimedAdditions = null;
		}
		else
		{
			pendingStealTick = tick;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INV)
		{
			return;
		}

		Multiset<Integer> current = snapshotInventory(event.getItemContainer());
		Multiset<Integer> previous = lastInventory;
		lastInventory = current;
		if (previous == null)
		{
			return;
		}

		Multiset<Integer> added = HashMultiset.create(Multisets.difference(current, previous));
		if (added.isEmpty())
		{
			return;
		}

		int tick = client.getTickCount();
		if (pendingStealTick != -1 && tick - pendingStealTick <= LOOT_WAIT_TICKS)
		{
			pendingStealTick = -1;
			recordSteal(added);
		}
		else
		{
			unclaimedAdditions = added;
			unclaimedAdditionsTick = tick;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (pendingStealTick != -1 && client.getTickCount() - pendingStealTick > LOOT_WAIT_TICKS)
		{
			log.debug("Steal message without any loot from {}", targetStall);
			pendingStealTick = -1;
		}
	}

	/**
	 * Called by the store from any thread
	 */
	private void onStoreChanged()
	{
		clientThread.invokeLater(this::refresh);
	}

	/**
	 * Recalculate overlay stats and push a priced snapshot to the panel. Prices can only be looked up on the
	 * client thread, so the panel never looks them up itself.
	 */
	private void refresh()
	{
		if (overlayStall != null)
		{
			StallRecord record = store.getSessionRecord(overlayStall);
			overlaySessionValue = valueOf(record);
			overlayRecord = record;
		}

		ThievingStallsPanel p = panel;
		if (p == null)
		{
			return;
		}

		List<StallRecord> session = store.getSession();
		List<StallRecord> allTime = store.getAllTime();
		Map<Integer, Long> prices = new HashMap<>();
		for (List<StallRecord> records : Arrays.asList(session, allTime))
		{
			for (StallRecord record : records)
			{
				for (LootItem item : record.getItems())
				{
					prices.computeIfAbsent(item.getId(), id -> priceOf(item));
				}
			}
		}
		PriceType priceType = config.priceType();
		int thievingXp = client.getGameState() == GameState.LOGGED_IN ? client.getSkillExperience(Skill.THIEVING) : -1;
		SwingUtilities.invokeLater(() -> p.update(session, allTime, prices, priceType, thievingXp));
	}

	private void recordSteal(Multiset<Integer> added)
	{
		String stall = targetStall != null ? targetStall : UNKNOWN_STALL;
		List<LootItem> loot = new ArrayList<>();
		for (Multiset.Entry<Integer> entry : added.entrySet())
		{
			ItemComposition composition = itemManager.getItemComposition(entry.getElement());
			loot.add(new LootItem(entry.getElement(), composition.getName(), entry.getCount(), composition.getHaPrice()));
		}

		// Claim xp that arrived before the loot this tick; xp arriving after is added in onStatChanged
		int tick = client.getTickCount();
		long xp = pendingXpTick != -1 && tick - pendingXpTick <= XP_WAIT_TICKS ? pendingXp : 0;
		pendingXp = 0;
		pendingXpTick = -1;
		lastStealStall = stall;
		lastStealTick = tick;
		lastStealHasXp = xp > 0;

		log.debug("Stole {} and {} xp from {}", loot, xp, stall);
		overlayStall = stall;
		store.record(stall, loot, xp, System.currentTimeMillis());
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.THIEVING)
		{
			return;
		}

		int xp = event.getXp();
		int previous = lastThievingXp;
		lastThievingXp = xp;
		// The first update after login is the current total, not a gain
		if (previous == -1 || xp <= previous)
		{
			return;
		}

		long gained = xp - previous;
		int tick = client.getTickCount();
		if (lastStealStall != null && !lastStealHasXp && tick - lastStealTick <= XP_WAIT_TICKS)
		{
			// xp arrived after the loot was recorded
			lastStealHasXp = true;
			store.addXp(lastStealStall, gained);
		}
		else
		{
			// Hold on to it in case loot is recorded this tick, otherwise it wasn't from a stall
			pendingXp = pendingXpTick == tick ? pendingXp + gained : gained;
			pendingXpTick = tick;
		}
	}

	/**
	 * Must be called on the client thread
	 */
	private long valueOf(StallRecord record)
	{
		if (record == null)
		{
			return 0;
		}

		long total = 0;
		for (LootItem item : record.getItems())
		{
			total += priceOf(item) * item.getQuantity();
		}
		return total;
	}

	/**
	 * Must be called on the client thread
	 */
	private long priceOf(LootItem item)
	{
		return config.priceType() == PriceType.HIGH_ALCHEMY
			? item.getHaPrice()
			: itemManager.getItemPrice(item.getId());
	}

	private static Multiset<Integer> snapshotInventory(ItemContainer container)
	{
		Multiset<Integer> items = HashMultiset.create();
		if (container != null)
		{
			for (Item item : container.getItems())
			{
				if (item.getId() > 0 && item.getQuantity() > 0)
				{
					items.add(item.getId(), item.getQuantity());
				}
			}
		}
		return items;
	}

	private static boolean isGameObjectOption(MenuAction action)
	{
		switch (action)
		{
			case GAME_OBJECT_FIRST_OPTION:
			case GAME_OBJECT_SECOND_OPTION:
			case GAME_OBJECT_THIRD_OPTION:
			case GAME_OBJECT_FOURTH_OPTION:
			case GAME_OBJECT_FIFTH_OPTION:
				return true;
			default:
				return false;
		}
	}
}

package com.thievingstalls;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.Reader;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.Callable;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Holds session and all-time stall loot, and persists all-time loot as one json file per stall:
 * {@code .runelite/plugin-data/thieving-stalls-loot-tracker/<account hash>/<stall>.json}
 * <p>
 * All file io runs on RuneLite's single-threaded {@link ScheduledExecutorService}, so writes and loads
 * happen in the order they are submitted. In-memory state is guarded by {@code this}.
 */
@Slf4j
@Singleton
public class LootStore
{
	private static final String EXTENSION = ".json";
	private static final long SAVE_DELAY_SECONDS = 5;

	private final ScheduledExecutorService executor;
	private final Gson gson;

	private final Map<String, StallRecord> session = new LinkedHashMap<>();
	private final Map<String, StallRecord> allTime = new LinkedHashMap<>();
	private final Set<String> dirty = new HashSet<>();

	private Filepath root;
	private Filepath accountDir;
	private long accountHash = -1;
	private boolean loaded;
	private ScheduledFuture<?> saveFuture;

	/**
	 * Called whenever loot data changes. May be invoked from any thread.
	 */
	@Setter
	private Runnable changeListener;

	@Inject
	LootStore(ScheduledExecutorService executor, Gson gson)
	{
		this.executor = executor;
		this.gson = gson.newBuilder().setPrettyPrinting().create();
	}

	/**
	 * Resolve the plugin data directory off the calling thread
	 */
	void start(Callable<Filepath> pluginDirectory)
	{
		executor.execute(() ->
		{
			try
			{
				Filepath dir = pluginDirectory.call();
				synchronized (this)
				{
					root = dir;
				}
			}
			catch (Exception e)
			{
				log.warn("Unable to resolve plugin data directory, loot will not be saved", e);
			}
		});
	}

	/**
	 * Flush pending writes. Does not block.
	 */
	synchronized void shutDown()
	{
		if (saveFuture != null)
		{
			saveFuture.cancel(false);
			saveFuture = null;
		}
		executor.execute(this::save);
	}

	/**
	 * Switch to the given account, saving the previous account's data first. Called on login.
	 */
	synchronized void setAccount(long hash)
	{
		if (hash == accountHash)
		{
			return;
		}

		if (accountHash != -1)
		{
			executor.execute(this::save);
		}

		// Submitted after the save above, so the previous account is fully written before we reset
		executor.execute(() -> load(hash));
	}

	synchronized void record(String stall, List<LootItem> loot, long xp, long time)
	{
		String slug = StallRecord.slugify(stall);
		session.computeIfAbsent(slug, s -> new StallRecord(stall)).addSteal(loot, xp, time);
		allTime.computeIfAbsent(slug, s -> new StallRecord(stall)).addSteal(loot, xp, time);
		dirty.add(slug);
		scheduleSave();
		notifyChanged();
	}

	/**
	 * Add xp to an already recorded steal, for when the xp drop arrives after the loot
	 */
	synchronized void addXp(String stall, long xp)
	{
		String slug = StallRecord.slugify(stall);
		StallRecord sessionRecord = session.get(slug);
		if (sessionRecord != null)
		{
			sessionRecord.setXp(sessionRecord.getXp() + xp);
		}
		StallRecord allTimeRecord = allTime.get(slug);
		if (allTimeRecord != null)
		{
			allTimeRecord.setXp(allTimeRecord.getXp() + xp);
			dirty.add(slug);
			scheduleSave();
		}
		notifyChanged();
	}

	/**
	 * @param slug the stall to reset, or null for every stall
	 */
	public synchronized void resetSession(String slug)
	{
		if (slug == null)
		{
			session.clear();
		}
		else
		{
			session.remove(slug);
		}
		notifyChanged();
	}

	/**
	 * Permanently delete all-time loot, including the json file(s) on disk
	 *
	 * @param slug the stall to reset, or null for every stall
	 */
	public synchronized void resetAllTime(String slug)
	{
		final List<String> removed = new ArrayList<>();
		if (slug == null)
		{
			removed.addAll(allTime.keySet());
			allTime.clear();
			dirty.clear();
		}
		else
		{
			allTime.remove(slug);
			dirty.remove(slug);
			removed.add(slug);
		}

		final Filepath dir = accountDir;
		if (dir != null)
		{
			executor.execute(() ->
			{
				for (String s : removed)
				{
					try
					{
						dir.joinSegment(s + EXTENSION).deleteIfExists();
					}
					catch (IOException | IllegalArgumentException e)
					{
						log.warn("Unable to delete loot file for {}", s, e);
					}
				}
			});
		}
		notifyChanged();
	}

	public synchronized List<StallRecord> getSession()
	{
		return sortedCopy(session);
	}

	public synchronized List<StallRecord> getAllTime()
	{
		return sortedCopy(allTime);
	}

	synchronized StallRecord getSessionRecord(String stall)
	{
		StallRecord record = session.get(StallRecord.slugify(stall));
		return record == null ? null : record.copy();
	}

	private static List<StallRecord> sortedCopy(Map<String, StallRecord> records)
	{
		return records.values().stream()
			.map(StallRecord::copy)
			.sorted(Comparator.comparingLong(StallRecord::getLastSteal).reversed())
			.collect(Collectors.toList());
	}

	private void scheduleSave()
	{
		if (saveFuture == null || saveFuture.isDone())
		{
			saveFuture = executor.schedule(this::save, SAVE_DELAY_SECONDS, TimeUnit.SECONDS);
		}
	}

	private void notifyChanged()
	{
		Runnable listener = changeListener;
		if (listener != null)
		{
			listener.run();
		}
	}

	/**
	 * Runs on the executor
	 */
	private void load(long hash)
	{
		Filepath dir;
		synchronized (this)
		{
			// Anything stolen before the account was known belongs to this account
			Map<String, StallRecord> pending = new LinkedHashMap<>();
			if (accountHash == -1)
			{
				for (String slug : dirty)
				{
					pending.put(slug, allTime.get(slug));
				}
			}
			else
			{
				session.clear();
			}

			accountHash = hash;
			accountDir = null;
			loaded = false;
			allTime.clear();
			allTime.putAll(pending);
			dirty.retainAll(pending.keySet());

			if (root == null)
			{
				log.warn("No plugin data directory, loot will not be saved");
				notifyChanged();
				return;
			}

			dir = root.joinSegment(Long.toString(hash));
		}

		Map<String, StallRecord> fromDisk = new LinkedHashMap<>();
		try
		{
			dir.createDirectories();
			try (Stream<Filepath> files = dir.walk(1))
			{
				for (Filepath file : (Iterable<Filepath>) files::iterator)
				{
					String name = file.getFileName();
					if (!file.isFile() || !name.endsWith(EXTENSION))
					{
						continue;
					}

					StallRecord record = read(file);
					if (record != null)
					{
						fromDisk.put(name.substring(0, name.length() - EXTENSION.length()), record);
					}
				}
			}
		}
		catch (IOException e)
		{
			log.warn("Unable to load stall loot from {}", dir, e);
			return;
		}

		synchronized (this)
		{
			if (accountHash != hash)
			{
				// switched accounts again while loading
				return;
			}

			for (Map.Entry<String, StallRecord> entry : fromDisk.entrySet())
			{
				StallRecord unsaved = allTime.get(entry.getKey());
				if (unsaved != null)
				{
					entry.getValue().merge(unsaved);
				}
				allTime.put(entry.getKey(), entry.getValue());
			}

			accountDir = dir;
			loaded = true;
			if (!dirty.isEmpty())
			{
				scheduleSave();
			}
			log.debug("Loaded {} stall loot files for account {}", fromDisk.size(), hash);
		}
		notifyChanged();
	}

	private StallRecord read(Filepath file)
	{
		try (Reader reader = file.openBufferedReader())
		{
			StallRecord record = gson.fromJson(reader, StallRecord.class);
			if (record == null)
			{
				return null;
			}
			if (record.getItems() == null)
			{
				record.setItems(new ArrayList<>());
			}
			return record;
		}
		catch (IOException | JsonParseException e)
		{
			log.warn("Unable to read {}, moving it aside", file, e);
			try
			{
				file.moveTo(file.getParent().joinSegment(file.getFileName() + ".corrupt-" + System.currentTimeMillis()));
			}
			catch (IOException | IllegalArgumentException ex)
			{
				log.warn("Unable to move corrupt file {}", file, ex);
			}
			return null;
		}
	}

	/**
	 * Runs on the executor
	 */
	private void save()
	{
		Filepath dir;
		Map<String, String> writes = new LinkedHashMap<>();
		synchronized (this)
		{
			if (!loaded || accountDir == null || dirty.isEmpty())
			{
				return;
			}

			dir = accountDir;
			for (String slug : dirty)
			{
				StallRecord record = allTime.get(slug);
				if (record != null)
				{
					writes.put(slug, gson.toJson(record));
				}
			}
			dirty.clear();
		}

		for (Map.Entry<String, String> write : writes.entrySet())
		{
			Filepath tmp = null;
			try
			{
				Filepath target = dir.joinSegment(write.getKey() + EXTENSION);
				tmp = dir.createTempFile(write.getKey(), ".tmp");
				tmp.write(write.getValue());
				try
				{
					tmp.moveTo(target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
				}
				catch (AtomicMoveNotSupportedException e)
				{
					tmp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
				}
			}
			catch (IOException | IllegalArgumentException e)
			{
				log.warn("Unable to save loot for {}", write.getKey(), e);
				deleteQuietly(tmp);
			}
		}
		log.debug("Saved {} stall loot files", writes.size());
	}

	private static void deleteQuietly(Filepath file)
	{
		if (file == null)
		{
			return;
		}
		try
		{
			file.deleteIfExists();
		}
		catch (IOException e)
		{
			log.debug("Unable to delete {}", file, e);
		}
	}
}

package com.thievingstalls.ui;

import com.thievingstalls.LootItem;
import com.thievingstalls.LootStore;
import com.thievingstalls.PriceType;
import com.thievingstalls.Rates;
import com.thievingstalls.StallRecord;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.SkillColor;
import net.runelite.client.ui.components.ProgressBar;
import net.runelite.client.util.QuantityFormatter;

public class ThievingStallsPanel extends PluginPanel
{
	private static final String SESSION = "Session";
	private static final String ALL_TIME = "All time";

	private final LootStore store;
	private final ItemManager itemManager;

	private List<StallRecord> sessionRecords = Collections.emptyList();
	private List<StallRecord> allTimeRecords = Collections.emptyList();
	private Map<Integer, Long> prices = Collections.emptyMap();
	private PriceType priceType = PriceType.GRAND_EXCHANGE;
	private int thievingXp = -1;

	private final JComboBox<String> viewSelector = new JComboBox<>(new String[]{SESSION, ALL_TIME});
	private final JLabel priceTypeLabel = new JLabel();
	private final StatsTable stats = new StatsTable("Steals", "Loot", "XP");
	private final ProgressBar levelBar = new ProgressBar();
	private final JPanel boxes = new JPanel();
	private final JLabel emptyLabel = new JLabel();

	@Inject
	ThievingStallsPanel(LootStore store, ItemManager itemManager)
	{
		// Not wrapped, so we can manage our own scroll pane and pin the reset button to the bottom
		super(false);
		this.store = store;
		this.itemManager = itemManager;

		setBorder(new EmptyBorder(6, 6, 6, 6));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setLayout(new BorderLayout(0, 6));

		// GridBagLayout skips hidden rows, so the level bar leaves no gap when hidden
		JPanel header = new JPanel(new GridBagLayout());
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setBorder(new EmptyBorder(8, 8, 8, 8));

		JPanel titleRow = new JPanel(new BorderLayout());
		titleRow.setOpaque(false);
		JLabel title = new JLabel("Thieving Stalls");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		priceTypeLabel.setFont(FontManager.getRunescapeSmallFont());
		priceTypeLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		titleRow.add(title, BorderLayout.WEST);
		titleRow.add(priceTypeLabel, BorderLayout.EAST);

		viewSelector.setFocusable(false);
		viewSelector.addActionListener(e -> rebuild());

		levelBar.setMaximumValue(100);
		levelBar.setBackground(new Color(61, 56, 49));
		levelBar.setForeground(SkillColor.find(Skill.THIEVING).getColor());

		addRow(header, titleRow, 0);
		addRow(header, viewSelector, 6);
		addRow(header, stats, 8);
		addRow(header, levelBar, 8);

		boxes.setLayout(new BoxLayout(boxes, BoxLayout.Y_AXIS));
		boxes.setOpaque(false);

		emptyLabel.setFont(FontManager.getRunescapeSmallFont());
		emptyLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		emptyLabel.setBorder(new EmptyBorder(8, 2, 0, 2));

		// Keep the boxes at their preferred height instead of stretching to fill the scroll pane
		JPanel boxesWrapper = new JPanel(new BorderLayout());
		boxesWrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		boxesWrapper.add(boxes, BorderLayout.NORTH);

		JScrollPane scrollPane = new JScrollPane(boxesWrapper);
		scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scrollPane.setBorder(BorderFactory.createEmptyBorder());
		scrollPane.getVerticalScrollBar().setUnitIncrement(16);

		JButton resetButton = new JButton("Reset all data");
		resetButton.setToolTipText("Delete all session and all-time loot for every stall");
		resetButton.addActionListener(e -> confirmResetAll());

		add(header, BorderLayout.NORTH);
		add(scrollPane, BorderLayout.CENTER);
		add(resetButton, BorderLayout.SOUTH);
	}

	private static void addRow(JPanel parent, Component component, int topGap)
	{
		GridBagConstraints c = new GridBagConstraints();
		c.gridx = 0;
		c.gridy = parent.getComponentCount();
		c.weightx = 1;
		c.fill = GridBagConstraints.HORIZONTAL;
		c.insets = new Insets(topGap, 0, 0, 0);
		parent.add(component, c);
	}

	private boolean isSessionView()
	{
		return SESSION.equals(viewSelector.getSelectedItem());
	}

	/**
	 * Replace the displayed data. Must be called on the EDT.
	 *
	 * @param prices unit price of every item in the records, looked up on the client thread
	 * @param thievingXp current thieving xp, or -1 if not logged in
	 */
	public void update(List<StallRecord> session, List<StallRecord> allTime, Map<Integer, Long> prices,
		PriceType priceType, int thievingXp)
	{
		this.sessionRecords = session;
		this.allTimeRecords = allTime;
		this.prices = prices;
		this.priceType = priceType;
		this.thievingXp = thievingXp;
		rebuild();
	}

	private long priceOf(LootItem item)
	{
		return prices.getOrDefault(item.getId(), 0L);
	}

	private void rebuild()
	{
		boolean session = isSessionView();
		List<StallRecord> records = session ? sessionRecords : allTimeRecords;

		long steals = 0;
		long value = 0;
		long xp = 0;
		long firstSteal = Long.MAX_VALUE;
		long lastSteal = 0;
		boxes.removeAll();
		for (StallRecord record : records)
		{
			steals += record.getSteals();
			xp += record.getXp();
			firstSteal = Math.min(firstSteal, record.getFirstSteal());
			lastSteal = Math.max(lastSteal, record.getLastSteal());
			for (LootItem item : record.getItems())
			{
				value += priceOf(item) * item.getQuantity();
			}
			String slug = record.getSlug();
			boxes.add(new StallBox(record, itemManager, this::priceOf, session, priceColor(priceType),
				session ? "Reset session" : "Delete all-time loot",
				() -> confirmReset(slug, record.getStall())));
		}

		if (records.isEmpty())
		{
			emptyLabel.setText("<html>No loot " + (session ? "this session" : "recorded")
				+ " yet. Steal from a stall to start tracking.</html>");
			boxes.add(emptyLabel);
		}

		priceTypeLabel.setText(priceType == PriceType.HIGH_ALCHEMY ? "HA prices" : "GE prices");
		priceTypeLabel.setToolTipText("Loot is valued at " + priceType + " prices. Change this in the plugin settings.");

		// Combined rates across every stall, from the first steal to the latest. Only meaningful for the
		// session, since all-time spans include time spent offline.
		long stealsPerHour = Rates.perHour(steals, steals, firstSteal, lastSteal);
		long gpPerHour = Rates.perHour(value, steals, firstSteal, lastSteal);
		long xpPerHour = Rates.perHour(xp, steals, firstSteal, lastSteal);
		stats.setShowRates(session);
		stats.setRow(0, QuantityFormatter.formatNumber(steals), formatRate(stealsPerHour), Color.WHITE, null);
		stats.setRow(1, QuantityFormatter.quantityToStackSize(value), formatRate(gpPerHour), priceColor(priceType),
			QuantityFormatter.formatNumber(value) + " gp");
		stats.setRow(2, QuantityFormatter.quantityToStackSize(xp), formatRate(xpPerHour), Color.WHITE,
			QuantityFormatter.formatNumber(xp) + " xp");

		// Progress through the current level, and time to the next at the session's xp rate.
		// Hidden at 99 or when logged out.
		int level = thievingXp == -1 ? -1 : Experience.getLevelForXp(thievingXp);
		boolean showLevel = session && level != -1 && level < Experience.MAX_REAL_LEVEL;
		levelBar.setVisible(showLevel);
		if (showLevel)
		{
			int levelStart = Experience.getXpForLevel(level);
			int levelEnd = Experience.getXpForLevel(level + 1);
			long remaining = levelEnd - thievingXp;
			long millis = Rates.millisToGain(remaining, xpPerHour);
			levelBar.setValue((int) (100L * (thievingXp - levelStart) / (levelEnd - levelStart)));
			levelBar.setLeftLabel("Lvl. " + level);
			levelBar.setRightLabel("Lvl. " + (level + 1));
			levelBar.setCenterLabel(millis == -1 ? "-" : Rates.formatHoursMinutes(millis));
			levelBar.setToolTipText("<html>" + QuantityFormatter.formatNumber(remaining) + " xp to level " + (level + 1)
				+ (millis == -1 ? "" : "<br>" + Rates.formatHoursMinutes(millis) + " (hh:mm) at your session xp rate")
				+ "</html>");
		}

		boxes.revalidate();
		boxes.repaint();
	}

	private static String formatRate(long perHour)
	{
		return perHour == -1 ? "-" : QuantityFormatter.quantityToStackSize(perHour);
	}

	static Color priceColor(PriceType priceType)
	{
		return priceType == PriceType.HIGH_ALCHEMY ? ColorScheme.GRAND_EXCHANGE_ALCH : ColorScheme.GRAND_EXCHANGE_PRICE;
	}

	private void confirmReset(String slug, String what)
	{
		boolean session = isSessionView();
		String message = session
			? "Reset session loot for " + what + "?"
			: "Permanently delete all-time loot for " + what + "? This deletes the saved json file.";
		int result = JOptionPane.showConfirmDialog(this, message, "Thieving Stalls", JOptionPane.YES_NO_OPTION);
		if (result != JOptionPane.YES_OPTION)
		{
			return;
		}

		if (session)
		{
			store.resetSession(slug);
		}
		else
		{
			store.resetAllTime(slug);
		}
	}

	private void confirmResetAll()
	{
		int result = JOptionPane.showConfirmDialog(this,
			"Permanently delete all session and all-time loot for every stall? This deletes the saved json files.",
			"Thieving Stalls", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
		if (result != JOptionPane.YES_OPTION)
		{
			return;
		}

		store.resetSession(null);
		store.resetAllTime(null);
	}
}

package com.thievingstalls.ui;

import com.thievingstalls.LootItem;
import com.thievingstalls.Rates;
import com.thievingstalls.StallRecord;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.Comparator;
import java.util.List;
import java.util.function.ToLongFunction;
import java.util.stream.Collectors;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.QuantityFormatter;

class StallBox extends JPanel
{
	private static final int ITEMS_PER_ROW = 5;

	/**
	 * @param showRates show hourly rates, only meaningful for session records
	 * @param valueColor color of the loot value, matching the price type
	 */
	StallBox(StallRecord record, ItemManager itemManager, ToLongFunction<LootItem> priceOf, boolean showRates,
		Color valueColor, String resetLabel, Runnable onReset)
	{
		setLayout(new BorderLayout(0, 1));
		setBorder(new EmptyBorder(5, 0, 0, 0));

		List<LootItem> items = record.getItems().stream()
			.sorted(Comparator.comparingLong((LootItem i) -> priceOf.applyAsLong(i) * i.getQuantity()).reversed())
			.collect(Collectors.toList());
		long total = items.stream().mapToLong(i -> priceOf.applyAsLong(i) * i.getQuantity()).sum();

		JPanel title = new JPanel(new GridLayout(2, 1, 0, 3));
		title.setBorder(new EmptyBorder(6, 7, 6, 7));
		title.setBackground(ColorScheme.DARKER_GRAY_COLOR.darker());
		if (record.getSteals() > 0)
		{
			title.setToolTipText(buildToolTip(record, total, showRates));
		}

		// Line 1: stall name and loot value
		JLabel nameLabel = label(record.getStall(), Color.WHITE);
		nameLabel.setMinimumSize(new Dimension(1, nameLabel.getPreferredSize().height));
		JLabel priceLabel = label(QuantityFormatter.quantityToStackSize(total) + " gp", valueColor);
		title.add(line(nameLabel, priceLabel));

		// Line 2: steal count, and rates for the session or total xp for all time
		String detail;
		if (showRates)
		{
			long gpPerHour = Rates.perHour(total, record.getSteals(), record.getFirstSteal(), record.getLastSteal());
			long xpPerHour = Rates.perHour(record.getXp(), record.getSteals(), record.getFirstSteal(), record.getLastSteal());
			detail = gpPerHour == -1 ? "" : QuantityFormatter.quantityToStackSize(gpPerHour) + " gp/hr  "
				+ QuantityFormatter.quantityToStackSize(xpPerHour) + " xp/hr";
		}
		else
		{
			detail = QuantityFormatter.quantityToStackSize(record.getXp()) + " xp";
		}
		String steals = QuantityFormatter.formatNumber(record.getSteals()) + (record.getSteals() == 1 ? " steal" : " steals");
		title.add(line(label(steals, ColorScheme.LIGHT_GRAY_COLOR), label(detail, ColorScheme.LIGHT_GRAY_COLOR)));

		add(title, BorderLayout.NORTH);
		add(buildItems(items, itemManager, priceOf), BorderLayout.CENTER);

		JPopupMenu popupMenu = new JPopupMenu();
		popupMenu.setBorder(new EmptyBorder(5, 5, 5, 5));
		JMenuItem reset = new JMenuItem(resetLabel);
		reset.addActionListener(e -> onReset.run());
		popupMenu.add(reset);
		setComponentPopupMenu(popupMenu);
		title.setComponentPopupMenu(popupMenu);
	}

	private static JPanel buildItems(List<LootItem> items, ItemManager itemManager, ToLongFunction<LootItem> priceOf)
	{
		JPanel container = new JPanel();
		container.setInheritsPopupMenu(true);
		int rows = Math.max(1, (items.size() + ITEMS_PER_ROW - 1) / ITEMS_PER_ROW);
		container.setLayout(new GridLayout(rows, ITEMS_PER_ROW, 1, 1));

		for (int i = 0; i < rows * ITEMS_PER_ROW; i++)
		{
			JPanel slot = new JPanel();
			slot.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			slot.setInheritsPopupMenu(true);

			if (i < items.size())
			{
				LootItem item = items.get(i);
				int quantity = (int) Math.min(item.getQuantity(), Integer.MAX_VALUE);
				JLabel image = new JLabel();
				image.setHorizontalAlignment(SwingConstants.CENTER);
				image.setVerticalAlignment(SwingConstants.CENTER);
				image.setInheritsPopupMenu(true);
				image.setToolTipText(buildToolTip(item, priceOf.applyAsLong(item)));
				itemManager.getImage(item.getId(), quantity, quantity > 1).addTo(image);
				slot.add(image);
			}

			container.add(slot);
		}
		return container;
	}

	private static JPanel line(JLabel left, JLabel right)
	{
		JPanel line = new JPanel(new BorderLayout(5, 0));
		line.setOpaque(false);
		line.setInheritsPopupMenu(true);
		line.add(left, BorderLayout.CENTER);
		line.add(right, BorderLayout.EAST);
		return line;
	}

	private static JLabel label(String text, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(color);
		return label;
	}

	private static String buildToolTip(StallRecord record, long total, boolean showRates)
	{
		StringBuilder tooltip = new StringBuilder("<html>")
			.append(QuantityFormatter.formatNumber(total)).append(" gp<br>")
			.append(QuantityFormatter.formatNumber(total / record.getSteals())).append(" gp per steal<br>")
			.append(QuantityFormatter.formatNumber(record.getXp())).append(" xp");

		if (showRates)
		{
			long stealsPerHour = Rates.perHour(record.getSteals(), record.getSteals(), record.getFirstSteal(), record.getLastSteal());
			long gpPerHour = Rates.perHour(total, record.getSteals(), record.getFirstSteal(), record.getLastSteal());
			tooltip.append("<br>Steals/hr: ")
				.append(stealsPerHour == -1 ? "-" : QuantityFormatter.formatNumber(stealsPerHour))
				.append("<br>GP/hr: ")
				.append(gpPerHour == -1 ? "-" : QuantityFormatter.formatNumber(gpPerHour) + " gp");

			long xpPerHour = Rates.perHour(record.getXp(), record.getSteals(), record.getFirstSteal(), record.getLastSteal());
			tooltip.append("<br>XP/hr: ")
				.append(xpPerHour == -1 ? "-" : QuantityFormatter.formatNumber(xpPerHour));
		}

		return tooltip.append("</html>").toString();
	}

	private static String buildToolTip(LootItem item, long price)
	{
		return "<html>" + item.getName() + " x " + QuantityFormatter.formatNumber(item.getQuantity())
			+ "<br>Price: " + QuantityFormatter.quantityToStackSize(price * item.getQuantity())
			+ " (" + QuantityFormatter.formatNumber(price) + " ea)</html>";
	}
}

package com.thievingstalls.ui;

import java.awt.Color;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * A small table of stats with a total column and an optional per hour column
 */
class StatsTable extends JPanel
{
	private final JLabel rateHeader = cell("Per hour", ColorScheme.LIGHT_GRAY_COLOR, SwingConstants.RIGHT);
	private final JLabel[] totals;
	private final JLabel[] rates;

	StatsTable(String... rowNames)
	{
		setOpaque(false);
		setLayout(new GridBagLayout());

		totals = new JLabel[rowNames.length];
		rates = new JLabel[rowNames.length];

		add(cell("", ColorScheme.LIGHT_GRAY_COLOR, SwingConstants.LEFT), 0, 0, 0);
		add(cell("Total", ColorScheme.LIGHT_GRAY_COLOR, SwingConstants.RIGHT), 1, 0, 1);
		add(rateHeader, 2, 0, 1);

		for (int i = 0; i < rowNames.length; i++)
		{
			totals[i] = cell("-", Color.WHITE, SwingConstants.RIGHT);
			rates[i] = cell("-", Color.WHITE, SwingConstants.RIGHT);
			add(cell(rowNames[i], ColorScheme.LIGHT_GRAY_COLOR, SwingConstants.LEFT), 0, i + 1, 0);
			add(totals[i], 1, i + 1, 1);
			add(rates[i], 2, i + 1, 1);
		}
	}

	void setRow(int row, String total, String rate, Color color, String tooltip)
	{
		totals[row].setText(total);
		totals[row].setForeground(color);
		totals[row].setToolTipText(tooltip);
		rates[row].setText(rate);
		rates[row].setForeground(color);
	}

	void setShowRates(boolean showRates)
	{
		rateHeader.setVisible(showRates);
		for (JLabel rate : rates)
		{
			rate.setVisible(showRates);
		}
	}

	private void add(JLabel label, int x, int y, double weight)
	{
		GridBagConstraints c = new GridBagConstraints();
		c.gridx = x;
		c.gridy = y;
		c.weightx = weight;
		c.fill = GridBagConstraints.HORIZONTAL;
		c.insets = new Insets(y == 0 ? 0 : 2, x == 0 ? 0 : 8, 0, 0);
		add(label, c);
	}

	private static JLabel cell(String text, Color color, int alignment)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(color);
		label.setHorizontalAlignment(alignment);
		return label;
	}
}

package com.thievingstalls;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@NoArgsConstructor
@AllArgsConstructor
public class LootItem
{
	private int id;
	private String name;
	private long quantity;
	/**
	 * High alchemy value of a single item, captured when the item was first looted
	 */
	private int haPrice;

	LootItem copy()
	{
		return new LootItem(id, name, quantity, haPrice);
	}
}

package com.thievingstalls;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Units;

@ConfigGroup(ThievingStallsConfig.GROUP)
public interface ThievingStallsConfig extends Config
{
	String GROUP = "thieving-stalls-loot-tracker";

	@ConfigItem(
		keyName = "priceType",
		name = "Price type",
		description = "Which price to use when valuing stolen loot",
		position = 0
	)
	default PriceType priceType()
	{
		return PriceType.GRAND_EXCHANGE;
	}

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show overlay",
		description = "Show an overlay with session stats for the stall you are stealing from",
		position = 1
	)
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overlayTimeout",
		name = "Overlay timeout",
		description = "Hide the overlay after this many minutes without a successful steal",
		position = 2
	)
	@Units(Units.MINUTES)
	default int overlayTimeout()
	{
		return 5;
	}
}
